-- Additive local-pipeline persistence. Applying this migration never publishes a story.
begin;
create type public.pipeline_candidate_status as enum ('discovered','watching','rejected','researching','research_blocked','ready_to_draft','drafting','verification_failed','editing','ready_for_review','revision_requested','approved','rejected_by_editor','archived');
create table public.pipeline_sources (id uuid primary key default gen_random_uuid(), name text not null, source_type text not null check(source_type in ('rss','atom','sitemap','homepage','website','search_query','manual_url')), locator text not null, enabled boolean not null default true, priority integer not null default 100, default_tags text[] not null default '{}', default_beats text[] not null default '{}', polling_frequency_minutes integer, last_checked_at timestamptz, last_successful_check_at timestamptz, failure_count integer not null default 0, notes text, created_at timestamptz not null default now());
create table public.discovery_runs (id uuid primary key default gen_random_uuid(), started_at timestamptz not null default now(), finished_at timestamptz, status text not null default 'running', counts jsonb not null default '{}', error text);
create table public.candidate_stories (id uuid primary key default gen_random_uuid(), cluster_key text unique not null, title text, canonical_url text, status public.pipeline_candidate_status not null default 'discovered', classification jsonb, model text, prompt_version text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.discovered_documents (id uuid primary key default gen_random_uuid(), candidate_id uuid references public.candidate_stories(id) on delete cascade, source_id uuid references public.pipeline_sources(id), url text not null, normalized_url text not null unique, canonical_url text, title text, description text, author text, published_at timestamptz, raw_discovery jsonb not null, fetched_at timestamptz, extraction_method text, extraction_status text, raw_html text, extracted_text text, paywalled boolean not null default false, created_at timestamptz not null default now());
create table public.research_packets (id uuid primary key default gen_random_uuid(), candidate_id uuid not null references public.candidate_stories(id) on delete cascade, iteration integer not null, packet jsonb not null, sufficiency jsonb, created_at timestamptz not null default now(), unique(candidate_id,iteration));
create table public.pipeline_runs (id uuid primary key default gen_random_uuid(), candidate_id uuid references public.candidate_stories(id) on delete cascade, model text not null, status text not null, started_at timestamptz not null default now(), finished_at timestamptz, artifact_path text, error text);
create table public.pipeline_stage_attempts (id uuid primary key default gen_random_uuid(), pipeline_run_id uuid not null references public.pipeline_runs(id) on delete cascade, stage text not null, attempt integer not null, raw_response text, validation_errors jsonb not null default '[]', metrics jsonb not null default '{}', created_at timestamptz not null default now(), unique(pipeline_run_id,stage,attempt));
create table public.pipeline_drafts (id uuid primary key default gen_random_uuid(), candidate_id uuid not null references public.candidate_stories(id) on delete cascade, version integer not null, headline text, dek text, body_markdown text not null, prior_draft_id uuid references public.pipeline_drafts(id), created_at timestamptz not null default now(), unique(candidate_id,version));
create table public.pipeline_claims (id uuid primary key default gen_random_uuid(), draft_id uuid not null references public.pipeline_drafts(id) on delete cascade, claim text not null, status text not null, note text, resolved_at timestamptz, resolved_by uuid references public.profiles(id));
create table public.pipeline_claim_sources (claim_id uuid references public.pipeline_claims(id) on delete cascade, document_id uuid references public.discovered_documents(id) on delete restrict, primary key(claim_id,document_id));
create table public.image_candidates (id uuid primary key default gen_random_uuid(), candidate_id uuid not null references public.candidate_stories(id) on delete cascade, original_url text not null, source_page text, creator text, caption text, license text, rights_status text not null check(rights_status in ('verified_reusable','official_press_asset','permission_required','unknown','do_not_use')), width integer, height integer, file_type text, proposed_role text, warning_flags text[] not null default '{}', selected boolean not null default false, created_at timestamptz not null default now());
create table public.pipeline_review_decisions (id uuid primary key default gen_random_uuid(), candidate_id uuid not null references public.candidate_stories(id) on delete cascade, actor_id uuid references public.profiles(id), action text not null check(action in ('approve','reject','request_revision','archive','edit','resolve_claim','remove_source','select_image','reject_image')), note text, created_at timestamptz not null default now());
create table public.pipeline_story_links (candidate_id uuid primary key references public.candidate_stories(id) on delete cascade, story_id uuid unique not null references public.stories(id) on delete restrict, created_at timestamptz not null default now());
alter table public.pipeline_sources enable row level security; alter table public.discovery_runs enable row level security; alter table public.candidate_stories enable row level security; alter table public.discovered_documents enable row level security; alter table public.research_packets enable row level security; alter table public.pipeline_runs enable row level security; alter table public.pipeline_stage_attempts enable row level security; alter table public.pipeline_drafts enable row level security; alter table public.pipeline_claims enable row level security; alter table public.pipeline_claim_sources enable row level security; alter table public.image_candidates enable row level security; alter table public.pipeline_review_decisions enable row level security;
alter table public.pipeline_story_links enable row level security;
create policy "editors manage local pipeline" on public.pipeline_sources for all to authenticated using(public.is_editor()) with check(public.is_editor());
create policy "editors read local pipeline candidates" on public.candidate_stories for select to authenticated using(public.is_editor());
create policy "editors manage local pipeline candidates" on public.candidate_stories for all to authenticated using(public.is_editor()) with check(public.is_editor());
create policy "editors read local pipeline data" on public.discovered_documents for select to authenticated using(public.is_editor()); create policy "editors manage local pipeline data" on public.discovered_documents for all to authenticated using(public.is_editor()) with check(public.is_editor());
create policy "editors manage local pipeline review" on public.pipeline_review_decisions for all to authenticated using(public.is_editor()) with check(public.is_editor());
create policy "editors manage pipeline story links" on public.pipeline_story_links for all to authenticated using(public.is_editor()) with check(public.is_editor());
commit;
